export type ContentfulAsset = {
  sys: {
    id: string;
  };
  fields: {
    title: string;
    description?: string;
    file: {
      url: string;
      fileName: string;
      contentType: string;
      details: {
        size: number;
        image?: {
          width: number;
          height: number;
        };
      };
    };
  };
};

export type ContentfulRichText = {
  nodeType: string;
  data: Record<string, unknown>;
  content: ContentfulRichTextNode[];
};

export type ContentfulRichTextNode = {
  nodeType: string;
  value?: string;
  data?: Record<string, unknown>;
  content?: ContentfulRichTextNode[];
  marks?: Array<{
    type: string;
  }>;
};

export type HomepageEntry = {
  sys: {
    id: string;
    contentType: {
      sys: {
        id: 'homepage';
      };
    };
  };
  fields: {
    heroBanner?: ContentfulAsset;
    duplexSection?: ContentfulRichText;
    videoEmbed?: ContentfulAsset;
    productHero?: string;
  };
};

export type Hotspot = {
  x: number;
  y: number;
  productId: string;
};

export type ShoppableImageEntry = {
  sys: {
    id: string;
    contentType: {
      sys: {
        id: 'shoppableImage';
      };
    };
  };
  fields: {
    title: string;
    image: ContentfulAsset;
    imageAlt?: string;
    hotspots: Hotspot[];
  };
};

export type AnyContentfulEntry = {
  sys: {
    id: string;
    contentType?: {
      sys: {
        id: string;
      };
    };
  };
  fields: Record<string, unknown>;
};

export type ContentfulResponse<T> = {
  sys: {
    type: string;
  };
  fields: T;
};

